SELECT '0011','0011_bcmd_batch_export.sql','7fe71e6bc3cc28600f9639441100ffccab08a74bc9fa45b905f017a478ea45d3'
WHERE @napa_pre_ok AND @napa_post_ok AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE version='0011');
